    image_patch = ImagePatch(image)
    women_patches = image_patch.find("woman")
    jeans_patches = image_patch.find("jeans")
    shirt_patches = image_patch.find("shirt")

    if not women_patches or not jeans_patches or not shirt_patches:
        return image_patch

    jeans_shirt_patches = []
    for w in women_patches:
        for j in jeans_patches:
            for s in shirt_patches:
                if w.overlaps_with(j.left, j.lower, j.right, j.upper) and w.overlaps_with(s.left, s.lower, s.right, s.upper):
                    jeans_shirt_patches.append((w, j, s))

    if not jeans_shirt_patches:
        return image_patch

    closest_patch = min(jeans_shirt_patches, key=lambda x: abs(x[0].vertical_center - 45))
    return closest_patch[0]

